#!/usr/bin/env bash
# init [--force]   Interactive wizard: asks for organisations, peer counts, channels... and writes network.yaml.
# Nothing is hard-coded: organisation names, peer counts and channel membership all come from the answers.
# Secrets are NOT asked for here - they are generated by `secrets init`.
set -euo pipefail
. "$(dirname "$0")/../lib/common.sh"
OUT="$CONFIG_FILE"
if [ -f "$OUT" ] && [ "${1:-}" != "--force" ]; then fatalln "$OUT exists - use 'init --force' to overwrite (or edit it by hand)"; fi

name_re='^[A-Za-z][A-Za-z0-9]{1,30}$'
ask() {  # ask "prompt" default -> REPLY
  local d="${2:-}" a; read -r -p "$1${d:+ [$d]}: " a; REPLY="${a:-$d}"
}
ask_name() {  # ask_name "prompt" default
  while :; do ask "$1" "${2:-}"; [[ "$REPLY" =~ $name_re ]] && return; echo "  use 2-31 letters/digits, starting with a letter"; done
}
ask_int() {  # ask_int "prompt" default min max
  while :; do ask "$1" "$2"; [[ "$REPLY" =~ ^[0-9]+$ ]] && [ "$REPLY" -ge "$3" ] && [ "$REPLY" -le "$4" ] && return; echo "  enter a number from $3 to $4"; done
}

echo "== Drunix network wizard =="
ask "Network name (prefix for docker objects)" "drunix"; net_name="$REPLY"
ask "Base domain" "example.io"; domain="$REPLY"
ask "Deployment mode (single-host / multi-host)" "single-host"; mode="$REPLY"
ask_name "Ordering-service organisation name" "NetworkAuthority"; oorg="$REPLY"
ask_int "Number of Raft orderers (1, 3 or 5)" 1 1 5; ocount="$REPLY"
[ "$ocount" = 2 ] || [ "$ocount" = 4 ] && fatalln "orderer count must be 1, 3 or 5"
ohosts=()
for ((i=1;i<=ocount;i++)); do
  if [ "$mode" = multi-host ]; then ask "Address of orderer$i" "localhost"; else REPLY=localhost; fi; ohosts+=("$REPLY")
done

ask_int "How many peer organisations" 2 1 20; nor="$REPLY"
orgs=(); declare -A cp lp vs hosts
for ((i=1;i<=nor;i++)); do
  while :; do ask_name "Organisation $i name" ""; n="$REPLY"
    [[ " ${orgs[*]:-} " == *" $n "* ]] && { echo "  already used"; continue; }; break; done
  orgs+=("$n")
  if [ "$mode" = multi-host ]; then ask "  address (host/IP) of $n" "localhost"; hosts[$n]="$REPLY"; else hosts[$n]=localhost; fi
  ask_int "  committing peers (CP) for $n" 1 1 9; cp[$n]="$REPLY"
  ask_int "  lite peers (LP) for $n - scale up for heavy tx load" 1 1 9; lp[$n]="$REPLY"
  ask_int "  VSCC validators for $n" 1 1 9; vs[$n]="$REPLY"
done

ask_int "How many channels" 1 1 50; nch="$REPLY"
chyaml=""
for ((c=1;c<=nch;c++)); do
  while :; do ask "Channel $c name (lowercase)" "channel$c"; ch="$REPLY"; [[ "$ch" =~ ^[a-z][a-z0-9.-]*$ ]] && break; echo "  lowercase letters, digits, . or -"; done
  echo "  organisations: ${orgs[*]}"
  while :; do ask "  members of '$ch' (names, comma separated)" "$(IFS=,; echo "${orgs[*]}")"; sel="$REPLY"
    ok=1; members=()
    IFS=',' read -ra parts <<<"$sel"
    for p in "${parts[@]}"; do p="${p// /}"; [[ " ${orgs[*]} " == *" $p "* ]] || { echo "  unknown organisation '$p'"; ok=0; }; members+=("$p"); done
    [ $ok = 1 ] && break; done
  ask "  endorsement policy (MAJORITY / ANY / ALL)" "MAJORITY"; pol="${REPLY^^}"
  ask "  batch timeout" "2s"; bt="$REPLY"
  ask_int "  max messages per block" 10 1 5000; bm="$REPLY"
  chyaml+="  - name: $ch"$'\n'"    organizations: [$(IFS=,; echo "${members[*]}" | sed 's/,/, /g')]"$'\n'
  chyaml+="    endorsement_policy: $pol"$'\n'"    batch: { timeout: $bt, max_message_count: $bm }"$'\n'
done
ask "Enable monitoring (Prometheus + Grafana)? (yes/no)" "yes"; mon=true; [[ "${REPLY,,}" =~ ^(n|no)$ ]] && mon=false

{
  echo "# Generated by './drunix-net.sh init' - edit freely, then run './drunix-net.sh generate'."
  echo "network: { name: $net_name, domain: $domain, mode: $mode }"
  echo "orderer:"; echo "  org_name: $oorg"; echo "  count: $ocount"
  echo "  hosts: [$(IFS=,; echo "${ohosts[*]}" | sed 's/,/, /g')]"
  echo "organizations:"
  for n in "${orgs[@]}"; do
    echo "  - name: $n"; echo "    host: ${hosts[$n]}"
    echo "    peers: { committing: ${cp[$n]}, lite: ${lp[$n]}, vscc: ${vs[$n]} }"
  done
  echo "channels:"; printf '%s' "$chyaml"
  echo "monitoring: { enabled: $mon }"
} > "$OUT"
okln "wrote ${OUT#$ROOT/}"
echo "Next: ./drunix-net.sh generate && ./drunix-net.sh secrets init && ./drunix-net.sh up"
